// Emits dist/tokens.css from the compiled token module.
import { writeFileSync } from "node:fs";
import { primitives, themes, toCss } from "../dist/index.js";

const css = [
  "/* Generated by @smrafi/tokens. Do not edit by hand. */",
  toCss(":root", primitives),
  toCss(':root, [data-theme="light"]', themes.light),
  toCss('[data-theme="dark"]', themes.dark),
  "@media (prefers-color-scheme: dark) {",
  toCss('  :root:not([data-theme="light"])', themes.dark).replace(/^/gm, "  ").trimEnd(),
  "}",
  "",
].join("\n");

writeFileSync(new URL("../dist/tokens.css", import.meta.url), css);
console.log(
  `tokens.css: ${Object.keys(primitives).length} primitives, ${Object.keys(themes.light).length} semantic tokens`,
);
